// +kcc:observedstate:proto=google.devicesandservices.health.v4.Sleep
type SleepObservedState struct {
	// Required. Observed sleep interval.
	// +kcc:proto:field=google.devicesandservices.health.v4.Sleep.interval
	Interval *SessionTimeIntervalObservedState `json:"interval,omitempty"`

	// Optional. List of non-overlapping contiguous sleep stage segments that
	//  cover the sleep period.
	// +kcc:proto:field=google.devicesandservices.health.v4.Sleep.stages
	Stages []Sleep_SleepStageObservedState `json:"stages,omitempty"`

	// Optional. Sleep metadata: `processed`, `main_sleep`, `manually_edited`, and
	//  `stages_status`.
	// +kcc:proto:field=google.devicesandservices.health.v4.Sleep.metadata
	Metadata *Sleep_SleepMetadataObservedState `json:"metadata,omitempty"`

	// Output only. Sleep summary: metrics and stages summary.
	// +kcc:proto:field=google.devicesandservices.health.v4.Sleep.summary
	Summary *Sleep_SleepSummaryObservedState `json:"summary,omitempty"`

	// Output only. Creation time of this sleep observation.
	// +kcc:proto:field=google.devicesandservices.health.v4.Sleep.create_time
	CreateTime *string `json:"createTime,omitempty"`

	// Output only. Last update time of this sleep observation.
	// +kcc:proto:field=google.devicesandservices.health.v4.Sleep.update_time
	UpdateTime *string `json:"updateTime,omitempty"`

	// Output only. List of short awake segments (under a set threshold) that are
	//  part of the sleep session. These can overlap with sleep stages.
	// +kcc:proto:field=google.devicesandservices.health.v4.Sleep.short_awakenings
	ShortAwakenings []Sleep_SleepStageObservedState `json:"shortAwakenings,omitempty"`
}

// +kcc:observedstate:proto=google.devicesandservices.health.v4.Sleep.SleepMetadata
type Sleep_SleepMetadataObservedState struct {
	// Output only. Sleep stages algorithm processing status.
	// +kcc:proto:field=google.devicesandservices.health.v4.Sleep.SleepMetadata.stages_status
	StagesStatus *string `json:"stagesStatus,omitempty"`

	// Output only. Sleep and sleep stages algorithms finished processing.
	//  A `true` value indicates whether all data processing for the session is
	//  complete.
	//  A `false` value means sleep period is detected but sleep stages is still
	//  processing.
	// +kcc:proto:field=google.devicesandservices.health.v4.Sleep.SleepMetadata.processed
	Processed *bool `json:"processed,omitempty"`

	// Output only. Naps are sleeps without stages and relatively short
	//  durations.
	// +kcc:proto:field=google.devicesandservices.health.v4.Sleep.SleepMetadata.nap
	Nap *bool `json:"nap,omitempty"`

	// Output only. Some sleeps autodetected by algorithms can be manually
	//  edited by users.
	// +kcc:proto:field=google.devicesandservices.health.v4.Sleep.SleepMetadata.manually_edited
	ManuallyEdited *bool `json:"manuallyEdited,omitempty"`

	// Output only. `main_sleep`: the longest sleep session with stages within
	//  one day. If no sleep session has stages, then the longest sleep is the
	//  `main_sleep`.  If there are multiple days of sleep in the response, there
	//  is one `main_sleep` per day.
	// +kcc:proto:field=google.devicesandservices.health.v4.Sleep.SleepMetadata.main_sleep
	MainSleep *bool `json:"mainSleep,omitempty"`
}

// +kcc:observedstate:proto=google.devicesandservices.health.v4.Sleep.SleepStage
type Sleep_SleepStageObservedState struct {
	// Required. Sleep stage start time.
	// +kcc:proto:field=google.devicesandservices.health.v4.Sleep.SleepStage.start_time
	StartTime *string `json:"startTime,omitempty"`

	// Required. The offset of the user's local time at the start of the sleep
	//  stage relative to the Coordinated Universal Time (UTC).
	// +kcc:proto:field=google.devicesandservices.health.v4.Sleep.SleepStage.start_utc_offset
	StartUtcOffset *string `json:"startUtcOffset,omitempty"`

	// Required. Sleep stage end time.
	// +kcc:proto:field=google.devicesandservices.health.v4.Sleep.SleepStage.end_time
	EndTime *string `json:"endTime,omitempty"`

	// Required. The offset of the user's local time at the end of the sleep
	//  stage relative to the Coordinated Universal Time (UTC).
	// +kcc:proto:field=google.devicesandservices.health.v4.Sleep.SleepStage.end_utc_offset
	EndUtcOffset *string `json:"endUtcOffset,omitempty"`

	// Required. Sleep stage type: AWAKE, DEEP, REM, LIGHT etc.
	// +kcc:proto:field=google.devicesandservices.health.v4.Sleep.SleepStage.type
	Type *string `json:"type,omitempty"`

	// Output only. Creation time of this sleep stages segment.
	// +kcc:proto:field=google.devicesandservices.health.v4.Sleep.SleepStage.create_time
	CreateTime *string `json:"createTime,omitempty"`

	// Output only. Last update time of this sleep stages segment.
	// +kcc:proto:field=google.devicesandservices.health.v4.Sleep.SleepStage.update_time
	UpdateTime *string `json:"updateTime,omitempty"`
}

// +kcc:observedstate:proto=google.devicesandservices.health.v4.Sleep.SleepSummary
type Sleep_SleepSummaryObservedState struct {
	// Output only. Delta between wake time and bedtime. It is the sum of all
	//  stages.
	// +kcc:proto:field=google.devicesandservices.health.v4.Sleep.SleepSummary.minutes_in_sleep_period
	MinutesInSleepPeriod *int64 `json:"minutesInSleepPeriod,omitempty"`

	// Output only. Minutes after wake up calculated by restlessness algorithm.
	// +kcc:proto:field=google.devicesandservices.health.v4.Sleep.SleepSummary.minutes_after_wake_up
	MinutesAfterWakeUp *int64 `json:"minutesAfterWakeUp,omitempty"`

	// Output only. Minutes to fall asleep calculated by restlessness algorithm.
	// +kcc:proto:field=google.devicesandservices.health.v4.Sleep.SleepSummary.minutes_to_fall_asleep
	MinutesToFallAsleep *int64 `json:"minutesToFallAsleep,omitempty"`

	// Output only. Total number of minutes asleep.
	//  For classic sleep it is the sum of ASLEEP stages (excluding AWAKE and
	//  RESTLESS). For "stages" sleep it is the sum of LIGHT, REM and DEEP stages
	//  (excluding AWAKE).
	// +kcc:proto:field=google.devicesandservices.health.v4.Sleep.SleepSummary.minutes_asleep
	MinutesAsleep *int64 `json:"minutesAsleep,omitempty"`

	// Output only. Total number of minutes awake. It is a sum of all AWAKE
	//  stages.
	// +kcc:proto:field=google.devicesandservices.health.v4.Sleep.SleepSummary.minutes_awake
	MinutesAwake *int64 `json:"minutesAwake,omitempty"`

	// Output only. List of summaries (total duration and segment count) per
	//  each sleep stage type.
	// +kcc:proto:field=google.devicesandservices.health.v4.Sleep.SleepSummary.stages_summary
	StagesSummary []Sleep_SleepSummary_StageSummaryObservedState `json:"stagesSummary,omitempty"`
}

// +kcc:observedstate:proto=google.devicesandservices.health.v4.Sleep.SleepSummary.StageSummary
type Sleep_SleepSummary_StageSummaryObservedState struct {
	// Output only. Sleep stage type: AWAKE, DEEP, REM, LIGHT etc.
	// +kcc:proto:field=google.devicesandservices.health.v4.Sleep.SleepSummary.StageSummary.type
	Type *string `json:"type,omitempty"`

	// Output only. Total duration in minutes of a sleep stage.
	// +kcc:proto:field=google.devicesandservices.health.v4.Sleep.SleepSummary.StageSummary.minutes
	Minutes *int64 `json:"minutes,omitempty"`

	// Output only. Number of sleep stages segments.
	// +kcc:proto:field=google.devicesandservices.health.v4.Sleep.SleepSummary.StageSummary.count
	Count *int64 `json:"count,omitempty"`
}

